package quebec.culture.donnees;
import android.content.*;import android.database.sqlite.*;import android.database.*;import java.util.*;
public class IndigenousDatabase extends SQLiteOpenHelper{public IndigenousDatabase(Context c){super(c,"indigenous_quebec.db",null,1);}@Override public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE nations(id INTEGER PRIMARY KEY,name TEXT,other_name TEXT,profile TEXT)");d.execSQL("CREATE TABLE history(id INTEGER PRIMARY KEY,year TEXT,title TEXT,detail TEXT)");String[][] n={{"Abénaquis","W8banaki","Nation abénaquise du Québec."},{"Algonquins","Anicinabek / Anishinaabeg","Nation anicinabe du Québec."},{"Attikameks","Atikamekw","Nation atikamekw du Québec."},{"Cris","Eeyou","Nation crie / Eeyou du Québec."},{"Wendat","Huron-Wendat","Nation huronne-wendat."},{"Innus","Innuat","Nation innue du Québec."},{"Inuit","Inuit","Nation inuit du Nunavik."},{"Wolastoqiyik","Wolastoqiyik Wahsipekuk","Nation wolastoqiyik."},{"Micmacs","Mi’gmaq","Nation mi’gmaq du Québec."},{"Mohawks","Kanien’kehá:ka","Nation kanien’kehá:ka."},{"Naskapis","Naskapi","Nation naskapie du Québec."}};for(String[] x:n){ContentValues v=new ContentValues();v.put("name",x[0]);v.put("other_name",x[1]);v.put("profile",x[2]);d.insert("nations",null,v);}String[][] h={{"1534","Premiers contacts européens documentés","Début d’une période de transformations profondes dans les relations, territoires et échanges."},{"1760","Changement de régime colonial","La Conquête britannique modifie les rapports politiques et juridiques."},{"1876","Loi sur les Indiens","Le cadre fédéral transforme profondément la gouvernance de nombreuses Premières Nations."},{"1975","Convention de la Baie-James et du Nord québécois","Accord majeur concernant notamment les Cris et les Inuit."},{"1978","Convention du Nord-Est québécois","Accord concernant notamment les Naskapis."},{"2002","Paix des Braves","Entente politique et économique entre le Québec et la Nation crie."},{"2019","Commission Viens","Rapport sur les relations entre les Autochtones et certains services publics au Québec."},{"Aujourd’hui","Cultures vivantes","Les 11 nations poursuivent leur développement culturel, linguistique, social et politique."}};for(String[] x:h){ContentValues v=new ContentValues();v.put("year",x[0]);v.put("title",x[1]);v.put("detail",x[2]);d.insert("history",null,v);}}@Override public void onUpgrade(SQLiteDatabase d,int o,int n){}public List<String[]> nations(){List<String[]> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT name,other_name,profile FROM nations ORDER BY id",null)){while(c.moveToNext())out.add(new String[]{c.getString(0),c.getString(1),c.getString(2)});}return out;}public List<String[]> history(){List<String[]> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT year,title,detail FROM history ORDER BY id",null)){while(c.moveToNext())out.add(new String[]{c.getString(0),c.getString(1),c.getString(2)});}return out;}}
